// TH18 v1.00a Extra stage 7 boss nonspell (st07bs.ecl.txt::Boss2:233-288).
// Source mapping is kept next to the code; see report.md for frame relation.
const TIME_LIMIT: int = 3780;      // 120 opening buffer + 60 setup wait + 3600 active slot
const OPENING_BUFFER: int = 120;

// TH18 type 12 logical row base (engine/touhou-bullets.ecl); color 14 is the
// native color slot, final appearance = shape base + color.
const TH18_ARROWHEAD: int = 544;

const BOSS_X: fx = 0fx;
const BOSS_Y: fx = 128fx;          // task: independent scene starts at (0,128)
const LIMIT_HALF_W: fx = 120fx;    // moveLimit(0,128,240,224): full width 240
const LIMIT_TOP: fx = 16fx;        // full height 224: y in [16,240]
const LIMIT_BOTTOM: fx = 240fx;
const RAND_INNER_X: fx = 60fx;     // the inner region for direction choice is width/4
const RAND_INNER_TOP: fx = 72fx;   // 128 +- 224/4
const RAND_INNER_BOTTOM: fx = 184fx;

const SHOT_SHAPE: int = TH18_ARROWHEAD;  // source etSprite(12,14)
const SHOT_COLOR: int = 14;
const SHOT_OFFSET_Y: fx = -24fx;         // source etOffset(0,-24)
const SHOT_DIST: fx = 32fx;              // source etDist(32)

// Source Boss2_at setup, reused verbatim for both async emitters.
const LANES: int = 4;                    // etCount(4,10)
const LAYERS: int = 10;
// The source loop is effectively endless (H=10000); the 3600-frame slot timeout
// ends it 60 frames after setup. Emitter windows: (3600-60)/10 = 354 waves.
const WAVE_FRAMES: int = 10;
const ACTIVE_WAVES: int = (3600 - 60) / WAVE_FRAMES;

// ---------------------------------------------------------------------------
// Minimal independent control shell (validation.md): control owns the phase.
// ---------------------------------------------------------------------------
async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // Real boss is invincible; body collision keeps the source normal circle box.
    _ = spawn_enemy(BOSS_X, BOSS_Y, 18000, 0, 0, 0, boss2);
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

// ---------------------------------------------------------------------------
// st07bs.ecl.txt::Boss2:233-288
// ---------------------------------------------------------------------------
async sub boss2() {
    // 235-236: invuln/life; the training shell keeps the real enemy invincible.
    set_invuln(65535);
    // Entry context carries setHurtbox(40,40)/setHitbox(48,48): circles 20/24.
    set_hurtbox(20fx);
    set_hitbox(24fx);
    // 237-254: TIMEOUT-dependent etCancel/etClear, bombShield, stars, BossItem,
    // timerReset, killAllAsync, enmKillAll, spellEnd, funcSet, laserCancel are
    // either empty-scene cleanup, rewards or presentation (public policy).
    // 266: setInterrupt(0,3000,3600,"BossCard2") gives the 3600-frame active slot,
    // represented by TIME_LIMIT in the shell; BossCard2 itself is not executed.
    // 260-262: stop residual velocity/position interpolation of the previous card.
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    // 272: source wait(60) before the two async emitters are created.
    wait(60);
    // 275-276: two independent Boss2_at contexts.
    spawn boss2_at(8deg, 1deg, -0.3deg);    // etEx ANGLE_ACCEL: +1deg/frame, layer step -0.3deg
    spawn boss2_at(-8deg, -1deg, 0.3deg);
    // 277-284: Boss2_1356 -> Boss2_1220 loop. moveRand(60,4,1.0) every 160 frames.
    loop {
        card_wait(100);
        card_move_rand();
        card_wait(60);
        card_wait(100);
        card_move_rand();
        card_wait(60);
    }
}

// ---------------------------------------------------------------------------
// st07bs.ecl.txt::Boss2_at:290-315 (one context per call)
// ---------------------------------------------------------------------------
async sub boss2_at(delta: angle, omega: angle, step: angle) {
    // 304: G = ANGLE_PLAYER, sampled once when the async context first runs.
    var g: angle = aim_player();
    var step_i: int = step as int;
    for wave in 0..ACTIVE_WAVES {
        // 296/298: 4 lanes x 10 layers. Mode 3 fixed-direction ring:
        // angle = G + R(i) + q*step, speed = 1.2 + (0-1.2)*q/(10-1).
        for q in 0..LAYERS {
            var v: fx = (54 - 6 * q) as fx / 45fx;   // 1.2 .. 0
            var dv: fx = (4fx - v) / 60fx;           // VELTIME a=60, target speed 4.0
            // ANIM a=1 birth retreat: position -= 4*velocity, along the shot angle.
            var dist: fx = SHOT_DIST - 4fx * v;
            for i in 0..LANES {
                var a: angle = ((g as int) + i * 16384 + q * step_i) as angle;
                var x: fx = $self_x + dist * cos(a);
                var y: fx = $self_y + SHOT_OFFSET_Y + dist * sin(a);
                _ = fire(SHOT_SHAPE, SHOT_COLOR, x, y, v, a, b2_ex(dv, omega), none);
            }
        }
        // 308-311
        g = g + delta;
        wait(10);
    }
}

// 299-301: ANIM (birth stage omitted per policy, retreat kept in spawn position),
// VELTIME 60 frames along the launch angle, then ANGLE_ACCEL 30 frames:
// speed += r(-0.1)/frame and angle += s(omega)/frame.
xformdef b2_ex(dv: fx, omega: angle) {
    @60 set_accel(dv);
    set_accel(-0.1fx);
    @30 set_ang_vel(omega);
    set_accel(0fx);
    set_ang_vel(0deg);
}

// ---------------------------------------------------------------------------
// movement.md moveRand(60,4,1.0) recipe, with this card's inherited limit
// moveLimit(0,128,240,224): x in [-120,120], y in [16,240].
// Slot ownership: self_int(0)=next movement step, self_fx(0/1)=logical unit
// vector; the two emitter tasks never touch these slots.
// ---------------------------------------------------------------------------
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60fx; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < 0fx - LIMIT_HALF_W { nx = 0fx - LIMIT_HALF_W; }
    if nx > LIMIT_HALF_W { nx = LIMIT_HALF_W; }
    if ny < LIMIT_TOP { ny = LIMIT_TOP; }
    if ny > LIMIT_BOTTOM { ny = LIMIT_BOTTOM; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

sub card_move_rand() {
    // 412: signed unit random * pi, then the horizontal branch.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < 0fx - RAND_INNER_X {
        a = r / 3;
    } else if $self_x > RAND_INNER_X {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < RAND_INNER_TOP {
        if a < 0 { a = -a; }
    } else if $self_y > RAND_INNER_BOTTOM {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, 0.05 rad in BAM (nearest integer boundaries).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
